import Foundation

// Mirror of android_js_widget_runtime JsWidgetRuntime / flutter QuickjsWidgetEngineBackend.
// Contract: JS -> host via global sendMessage(channel, payloadJson);
// host -> JS via jsr._handler(actionId, payload) (callEvent).
// Bootstrap order (family plan section 1.2): __IID, runtime half, widget half —
// the two halves load from Bundle.module (generated by scripts/sync-bootstrap.sh).
public final class JsWidgetRuntime {
    public typealias MessageSink = (_ channel: String, _ payload: String) -> Void

    private let engine: JsEngine
    private var sink: MessageSink?

    public init(engine: JsEngine) {
        self.engine = engine
        engine.setMessageCallback { [weak self] channel, payload in
            self?.sink?(channel, payload)
        }
    }

    /// Evaluates `__IID`, then the runtime half, then the widget half (Bundle.module).
    public func start(sink: @escaping MessageSink, iid: String) throws {
        self.sink = sink
        let bundle = Bundle.module
        let runtimeHalf = try String(contentsOf: bundle.url(forResource: "bootstrap-runtime", withExtension: "js")!, encoding: .utf8)
        let widgetHalf = try String(contentsOf: bundle.url(forResource: "bootstrap-widget", withExtension: "js")!, encoding: .utf8)
        try engine.eval("var __IID = \"\(iid)\";", sourceName: "<iid>")
        try engine.eval(runtimeHalf, sourceName: "bootstrap-runtime.js")
        try engine.eval(widgetHalf, sourceName: "bootstrap-widget.js")
    }

    /// Delivers an event into the widget: jsr._handler(actionId, payloadJson).
    /// Contract-identical to the Flutter/Android dispatch snippet; drains pending
    /// jobs afterwards (promise handlers run before the host continues).
    public func callEvent(_ actionId: String, payloadJson: String = "{}") throws {
        let escapedAction = actionId.replacingOccurrences(of: "\"", with: "\\\"")
        let script = """
        (function(){
          var __h = jsr._handler || (typeof handleEvent === "function" ? handleEvent : null);
          if (!__h) { return; }
          try {
            var __r = __h("\(escapedAction)", \(payloadJson));
            if (__r && typeof __r.then === "function") { __r.then(function(){}, function(e){}); }
          } catch (e) {}
        })();
        """
        try engine.eval(script, sourceName: "<event>")
        engine.executePendingJobs()
    }
}
